    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        // Only reenter once
        if (doReenter && !reentered) {
            reentered = true;
            // attempt to call initialize again on target with a different nft value to try to change nft()
            // Use innocuous other parameters
            try target.initialize(address(0), reenterWith, 1, 1, 0, 0, bytes32(0), false, false) {
                // ignore
            } catch {
                // ignore
            }
        }
        return bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
    }
}

